using Health_Care_System.BLL.Interfaces; using Health_Care_System.BLL.Models; using Health_Care_System.Entities;
namespace Health_Care_System.BLL.Services;
public sealed class DoctorService:IDoctorService { private readonly IUnitOfWork _uow; public DoctorService(IUnitOfWork uow)=>_uow=uow; private IGenericRepository<Doctor> Repo=>_uow.Doctors; public async Task<Result<PaginatedList<Doctor>>> GetAllAsync(string? searchValue,int pageIndex,int pageSize){var data=string.IsNullOrWhiteSpace(searchValue)?await Repo.GetAllAsync():await Repo.SearchAsync(searchValue);return Result<PaginatedList<Doctor>>.Success(PaginatedList<Doctor>.Create(data,pageIndex,pageSize));} public async Task<Result<Doctor>> GetByIdAsync(int id){var item=await Repo.GetAsync(id);return item is null?Result<Doctor>.Failure("Doctor not found."):Result<Doctor>.Success(item);} public async Task<Result<Doctor>> CreateAsync(Doctor entity){await Repo.CreateAsync(entity);await _uow.SaveChangesAsync();return Result<Doctor>.Success(entity);} public async Task<Result<Doctor>> UpdateAsync(Doctor entity){var existing=await Repo.GetAsync(entity.Id);if(existing is null)return Result<Doctor>.Failure("Doctor not found."); Copy(entity,existing);Repo.Update(existing);await _uow.SaveChangesAsync();return Result<Doctor>.Success(existing);} public async Task<Result<Doctor>> DeleteAsync(int id){var item=await Repo.GetAsync(id);if(item is null)return Result<Doctor>.Failure("Doctor not found.");Repo.Delete(item);await _uow.SaveChangesAsync();return Result<Doctor>.Success(item);} private static void Copy(Doctor source,Doctor target){target.Name=source.Name;target.Specialization=source.Specialization;}}
